// WF04 v3 (14 Oct 2026): prompts follow John's script skills
//   alfredai-news-script-generator v3.0, alfredai-education-script-generator v2.0, product-themed-script-generator.
// Shared: Initial Anticipation > Loading > Rising Stakes > Rehook > Practical Payoff > CTA,
// topic/audience-driven hook family (Controversy, Authority, Curiosity, Relatability, Storytelling),
// no back-to-back repeat of the previous script's family or phrasing, scene timing, editing rhythm,
// platform captions, YouTube package, ManyChat flow, manual review brief and QA checklist.
// The model returns ONE JSON object; node 5 turns it into the Airtable fields.
const record = $('1c. Batch of 1').first().json;
const patterns = $('2. Get Viral Patterns & Transcripts').all();
const recent = $('2b. Get Recent Hooks').all().map(i => i.json).filter(r => r && r.id && r.id !== record.id);
// The idea's own source video (Viral Library row with the same URL): factual source material, not structure.
let sourceRow = {};
try { sourceRow = $('2c. Get Source Transcript').first().json || {}; } catch (e) { sourceRow = {}; }
const sourceTranscript = String(sourceRow['Transcript'] || '').trim();
const sourceText = (sourceTranscript && sourceTranscript !== 'TRANSCRIPT_UNAVAILABLE') ? sourceTranscript.substring(0, 4000) : '';

const sel = v => (v && typeof v === 'object') ? (v.name || '') : String(v || '');
const topic = String(record['Topic'] || '').trim();
const rawCategory = sel(record['Category']).trim();
const platform = sel(record['Platform']) || 'YouTube';
const contentType = sel(record['Content Type']) || 'Video';
const sourceName = String(record['Source Name'] || '').trim();
const sourceUrl = String(record['Source URL'] || '').trim();
const angle = String(record['Suggested_Angle'] || '').trim();

// Same theme mapping as WF06 avatar selection, so script skill and avatar always agree.
const SKILL_MAP = { 'News': 'News', 'Business': 'News', 'Tech': 'News', 'Entertainment': 'News', 'Other': 'News', 'General': 'News', '': 'News',
  'Education': 'Education', 'Health': 'Education', 'Lifestyle': 'Education', 'Motivation': 'Education', 'Comedy': 'Education',
  'Product': 'Product', 'Product Intro': 'Product' };
const skill = SKILL_MAP[rawCategory] || 'News';

const srcUrl = String(record['Source URL'] || '').trim();
const usable = patterns.filter(p => { const t = String(p.json['Transcript'] || '').trim(); return t && t !== 'TRANSCRIPT_UNAVAILABLE' && String(p.json['URL'] || '').trim() !== srcUrl; });
const pool = usable.length ? usable : patterns;
const pattern = pool.length ? pool[Math.floor(Math.random() * pool.length)].json : {};
const transcript = String(pattern['Transcript'] || '').substring(0, 2000);

// Previous scripts in the content sequence (newest first), for hook-family and phrasing rotation.
const firstLine = s => String(s || '').trim().split(/\n+/)[0].substring(0, 200);
const pickLine = (txt, key) => { const m = String(txt || '').match(new RegExp('^' + key + ':\\s*(.+)$', 'mi')); return m ? m[1].trim() : ''; };
const prev = recent.slice(0, 5).map((r, i) => {
  const fam = sel(r['Hook_Family']);
  const cat = sel(r['Category']);
  let line = (i + 1) + '. ' + (fam || 'unknown') + ' | ' + (cat || '-') + ' | opening: "' + firstLine(r['Script']) + '"';
  const trade = pickLine(r['Script_Review_Brief'], 'Trade');
  const demo = pickLine(r['Script_Review_Brief'], 'Demo');
  if (trade || demo) line += ' | trade/demo: ' + trade + ' / ' + demo;
  return line;
});
const lastFamily = recent.length ? sel(recent[0]['Hook_Family']) : '';

const HOOKS = {
  News: [
    'Controversy: the story exposes a disagreement or challenges a popular belief. Formats: direct challenge, contrarian reframe, "the industry does not agree...".',
    'Authority: a credible person, company or number gives the story weight. Formats: high-stakes fact, named decision, authority principle.',
    'Curiosity: the important detail is hidden behind the headline. Formats: hidden flaw, withheld information, "here is what they did not tell you...".',
    'Relatability: the story mirrors a decision or uncertainty the viewer already feels. Formats: "If you are watching this from operations...", a familiar work moment.',
    'Storytelling: the story has a sequence, reversal, conflict or unusual human decision. Formats: "First this happened. Then the unexpected part...".'
  ],
  Education: [
    'Controversy: the lesson challenges a common belief. Formats: "The popular advice is wrong", "stop learning the wrong thing".',
    'Authority: a credible source or expert supports the lesson. Formats: "A major report suggests...", "the one principle leaders use...".',
    'Curiosity: the answer is useful but not obvious. Formats: "The most important skill is not...", "here is what people leave out...".',
    'Relatability: the viewer recognises the situation from work or career. Formats: "If you work in construction and keep seeing...".',
    'Storytelling: the lesson is best understood through a sequence or scenario. Formats: "Imagine the first week after...", "this is what changed...".'
  ],
  Product: [
    'Controversy: the viewer relies on a familiar but weak method. Example: "Another generic chatbot will not solve this trade workflow."',
    'Authority: the lesson is a clear buying or implementation principle. Example: "The first thing to check before automating this process is..."',
    'Curiosity: the hidden cost or missing handoff is the strongest angle. Example: "The part of this workflow nobody shows you is..."',
    'Relatability: the trade\'s daily struggle creates immediate recognition. Example: "If you are a [trade] still doing [specific pain], this is for you."',
    'Storytelling: a before-and-after scenario makes the workflow easier to understand. Example: "If I woke up tomorrow with this problem, here is exactly what I would do."'
  ]
};

const RUNTIME = { News: '60-90 seconds (about 130-195 spoken words at 130 wpm)', Education: '45-60 seconds (about 100-130 spoken words at 130 wpm)', Product: 'under 2 minutes; prefer 60-110 seconds (about 130-240 spoken words at 130 wpm)' };

const SHARED_RULES = [
  'HOOK FAMILY SELECTION (mandatory):',
  '- Choose exactly one family from the list below based on the topic\'s conflict, the audience and the evidence. Never choose randomly.',
  '- Do NOT use the same family as the immediately previous script' + (lastFamily ? ' (previous: ' + lastFamily + ')' : '') + ', and do not reuse the sentence pattern of any recent opening listed below.',
  '- Controversy only when the topic contains a real disagreement or a widely held belief the evidence contradicts; otherwise use the family that matches the evidence (Authority for a credible source or number, Curiosity for a hidden detail, Relatability for a familiar work moment, Storytelling for a sequence or reversal).',
  '- Record the family and the exact hook format you used.',
  '',
  'PREVIOUS SCRIPTS IN THE CONTENT SEQUENCE (newest first):',
  prev.length ? prev.join('\n') : '(none recorded yet)',
  '',
  'PSYCHOLOGY STRUCTURE (every script, in this order; one or more scenes per beat):',
  '1. Initial Anticipation - open with a conflict, unusual fact, direct challenge or unanswered question; make the viewer ask what is going on.',
  '2. Loading - build with evidence, examples, named positions or specific detail; delay the final interpretation without filler.',
  '3. Rising Stakes - show why it matters: consequences for decisions, money, risk, trust or control.',
  '4. Rehook - after a first reveal, open a second meaningful question with a clean transition; no fake cliffhanger.',
  '5. Practical Payoff - resolve every open loop; state what it means and what to do; keep it grounded in the evidence.',
  '6. CTA - one clear action only.',
  '',
  'EDITING AND PACING (put these into each scene\'s visual and on_screen_text notes, and summarise in editing_notes):',
  '- The opening visual and on-screen hook land within the first 1-2 seconds.',
  '- Change the visual state every 2-4 seconds (direct-to-camera cuts, text cards, diagrams, source snippets, examples).',
  '- Faster cuts while loading evidence; a short pause before the rehook; slow slightly in the payoff.',
  '- Hold the final CTA on screen for at least 3 seconds.',
  '- On-screen text is shorter than the spoken sentence; never a full paragraph on screen.',
  '- Never use editing to imply certainty, evidence or automation that does not exist.',
  '',
  'LANGUAGE: short sentences, simple words, one idea per sentence, peer-to-peer, no hype, no fearmongering, no corporate filler, no emojis in the spoken copy.',
  'FACTS: use only facts from the TOPIC, SOURCE and ANGLE below or well-established general knowledge. Never invent statistics, quotes, studies, case studies, dates or certainty. Anything time-sensitive or uncertain goes into review_brief.checks as something to verify before publishing.',
  'SPOKEN COPY: each scene\'s "spoken" value is exactly what the avatar says - no labels, no stage directions, no brackets, no markdown, no emojis.'
].join('\n');

let skillBlock = '';
let metaSpec = '';
if (skill === 'News') {
  skillBlock = [
    'SKILL: AlfredAI Thought Leadership / Commentary Script Generator v3.0 (news-first commentary, not a news bulletin and not a product pitch).',
    'WORKFLOW: separate confirmed facts, attributed opinions, interpretation and unresolved claims. Reduce the story to one sentence: what happened and what most people misunderstand (the central gap). Pick ONE primary viewer (construction owner, operations leader, project director, digital leader or AI decision-maker) and the implication that matters to them. Find the natural construction connection.',
    'GUARDRAILS (non-negotiable):',
    '- Spoken script and public captions are unbranded. Never mention AlfredAI, a product feature or a product demo.',
    '- No news-anchor framing ("Breaking news", "I\'m reporting on").',
    '- Attribute claims with said, called for, backed, warned, argued, proposed or rejected.',
    '- Construction is a natural final connection or broader implication, never a sales pivot.',
    '- One engagement CTA; a comment keyword is preferred (then ManyChat applies).',
    '- Do not default to "X is officially dead". Rotate implication language: we are moving toward, the new baseline is, the old assumption is weakening, the decision has changed, this exposes a larger shift.',
    '- Rehook transitions that fit: "That is the part most people are missing." / "But the disagreement is where this gets interesting." / "And this changes the question for construction."',
    '- Voice: conversational, observational, calm, punchy; an informed peer.',
    'TARGET RUNTIME: ' + RUNTIME.News + '.'
  ].join('\n');
  metaSpec = '{"topic": "", "primary_audience": "", "central_gap": "", "target_runtime": "60-90 seconds", "cta": "keyword or engagement action", "source_status": "fact-check note: what is confirmed, attributed or unresolved"}';
} else if (skill === 'Education') {
  skillBlock = [
    'SKILL: AlfredAI Education Script Generator v2.0 (direct-to-camera lesson, curiosity-led, no product pitch).',
    'WORKFLOW: write the single lesson in one sentence; identify the common assumption it challenges; choose one credible source or authority; name ONE primary viewer (estimator, project manager, construction leader, apprentice, operations lead or similar) and why it matters to them now.',
    'EDUCATION PATTERN INSIDE THE SHARED STRUCTURE: Curiosity hook (withhold the answer) = Initial Anticipation. Authority reference and teaser/misdirection (eliminate one or two obvious answers) = Loading and Rising Stakes. Reveal = Rehook (reveal the insight, then open one final question). Why + construction context + one or two concrete actions = Practical Payoff. Save/share CTA = CTA.',
    'Approximate timing: Initial Anticipation 0:00-0:05, Loading 0:05-0:18, Rising Stakes 0:18-0:30, Rehook 0:30-0:36, Practical Payoff 0:36-0:53, CTA 0:53-1:00.',
    'GUARDRAILS (non-negotiable):',
    '- Spoken script and public captions are unbranded. Never mention AlfredAI, a product or a demo; no sales pitch; do not argue one narrow operational pain point as a sales angle.',
    '- Do not reveal the core insight in the first sentence.',
    '- Credible references only; never invent studies, statistics, quotes or predictions; no fear-based career claims.',
    '- CTA is save, share or follow. Use a comment keyword only if a real follow-up resource exists - assume it does not, so ManyChat is normally not applicable.',
    '- Voice: helpful mentor, speaks to "you", confident without overclaiming, practical example over abstraction.',
    'TARGET RUNTIME: ' + RUNTIME.Education + '.'
  ].join('\n');
  metaSpec = '{"lesson": "", "primary_audience": "", "challenged_assumption": "", "authority_source": "", "target_runtime": "45-60 seconds", "cta_type": "save / share / follow"}';
} else {
  const painDb = "Estimators:\n- 1. Manual takeoff errors: Manual quantity extraction from complex PDFs is slow and prone to human error, leading to inaccurate bids.\n- 2. Outdated material pricing: Fluctuating material costs mean estimators waste hours manually updating spreadsheets, risking outdated bids.\n- 3. Rushed bid deadlines: The high volume of tender requests means estimators rush through bids or miss deadlines entirely.\n- 4. Disconnected PM data: Data silos between estimating software and PM tools lead to miscommunication and cost overruns during execution.\n- 5. Historical bid comparison: Historical pricing data is buried in old folders, making it impossible to leverage past success for new bids.\n- 6. Last-minute addendums: Late changes to scope require manual recalculations across multiple spreadsheets, risking catastrophic errors.\n\nQuantity Surveyors (QS):\n- 7. Manual variation tracking: Chasing down site teams for variation details and manually updating cost reports leads to disputed final accounts.\n- 8. Tedious pay app reviews: Manually cross-checking subcontractor invoices against work completed is slow, tedious, and delays payments.\n- 9. Poor cost-to-complete visibility: Gathering data from fragmented systems means cost reports are reactive, not proactive.\n- 10. Contract dispute resolution: When disputes arise, finding the specific email or RFI to prove your case is like finding a needle in a haystack.\n- 11. Time-consuming lifecycle costing: Gathering the long-term maintenance and operational data required for accurate lifecycle costing is highly manual.\n- 12. BOQ vs. site usage discrepancies: Tracking the variance between the initial BOQ and actual material usage requires constant, manual reconciliation.\n\nProject Managers:\n- 13. Drowning in RFI management: Manually routing RFIs, chasing architects for answers, and updating the site team causes massive delays.\n- 14. Fragmented communication: Critical project decisions are scattered across personal devices, creating compliance risks and confusion.\n- 15. Delayed daily site reports: Site managers spend hours writing reports, meaning PMs don't get the data until it's too late to act.\n- 16. Subcontractor coordination: Manually adjusting schedules when one trade is delayed causes a domino effect of chaos across the site.\n- 17. Missing compliance documentation: Chasing subcontractors for safety inductions and compliance docs is a massive administrative headache.\n- 18. Manual status update meetings: PMs spend hours compiling data just to tell stakeholders what happened three days ago.\n- 19. Managing handover and defects: Managing hundreds of minor defects via spreadsheets leads to missed items and delayed final payments.\n\nBuilders / Developers:\n- 20. Slow feasibility studies: Gathering zoning data, cost estimates, and market analysis manually slows down critical investment decisions.\n- 21. Finance vs. construction data: Developers struggle to reconcile construction progress with drawdowns because the data lives in different silos.\n- 22. Complex stakeholder reporting: Compiling monthly reports for investors, banks, and partners requires pulling data from a dozen different sources.\n- 23. Permitting approval delays: Navigating complex local regulations and ensuring every application is perfect is highly manual and prone to rejection.\n- 24. Scaling without bloating overhead: Growing a development business usually means hiring armies of admins to manage the paperwork.\n- 25. Tracking legacy warranty claims: Tracking which contractor is responsible for a defect years after completion relies on lost emails and dead spreadsheets.\n\nFlooring Contractors & Specialists:\n- 26. Sales to installer handoff failures: Incomplete job handoffs mean installers arrive on site missing materials or unaware of specific site conditions.\n- 27. Inaccurate measurements and waste: Manual measurements and estimations lead to either shortfalls that delay jobs or excess waste that eats profits.\n- 28. Chasing GCs for payment: Submitting manual pay apps that get rejected for minor formatting errors delays cash flow for weeks.\n- 29. Predecessor trade delays: Sending a crew to a site only to find the drywallers aren't finished costs thousands in wasted labor.\n- 30. High volume of small quotes: The administrative burden of quoting small jobs manually outweighs the profit margin on the work itself.\n- 31. Tracking material lead times: Manually tracking lead times across dozens of suppliers leads to scheduling disasters and unhappy clients.\n\nConstruction Business Owners & Operators:\n- 32. Unpredictable cash flow: Manual invoicing and delayed AR tracking mean cash goes out for payroll weeks before it comes in from clients.\n- 33. Leadership burnout: Owners are stuck in the weeds of daily operations, unable to focus on high-level strategy and growth.\n- 34. Inaccurate profit forecasting: Data is siloed across estimating, PM, and accounting software, making accurate financial forecasting impossible.\n- 35. High staff turnover: Highly skilled PMs and estimators are quitting because they spend 70% of their time doing administrative paperwork.\n- 36. Legacy software replacement risk: Owners want better technology but are terrified of the downtime and training required to replace their current systems.\n- 37. Lack of standardized processes: Without standardized workflows, quality and profitability vary wildly from project to project.\n- 38. Hitting the revenue ceiling: The manual processes that got a company to $5M completely break down when trying to scale further.\n\nEstimators & Sales Teams:\n- 39. Quoting unqualified leads: Manually filtering through tire-kickers and unqualified leads takes time away from high-value prospects.\n- 40. Slow response times: When an estimator takes three days to return a quote, the client has already signed with a competitor.\n- 41. Dropped follow-ups: Sales teams send out quotes but lack the time to consistently follow up, leaving money on the table.\n- 42. Sales vs. estimating disconnect: Sales teams lack real-time access to current estimating costs, leading to inaccurate verbal quotes.\n- 43. Inefficient CRM usage: Sales reps hate manually logging calls and updating CRM statuses, so the data is always inaccurate.\n- 44. Tracking win/loss ratios: Without easy access to win/loss data, teams keep bidding on project types they historically lose money on.\n\nResidential & Commercial Trade Businesses:\n- 45. Chaotic dispatching: Manual scheduling leads to inefficient routes, late arrivals, and frustrated customers.\n- 46. Uncaptured change orders: Field workers do extra work but fail to process the formal change order, meaning the business never gets paid for it.\n- 47. After-hours emergency calls: Managing an after-hours emergency roster is stressful and prone to missed calls.\n- 48. Van inventory shrinkage: Tracking small parts across a fleet of vehicles is impossible manually, leading to stockouts and delays.\n- 49. Inconsistent customer updates: Customers call the office constantly because they don't know when the tech is arriving or if the part is ordered.\n- 50. Transitioning to commercial work: Commercial work requires massive compliance, complex pay apps, and strict data governance that residential tools can't handle.";
  skillBlock = [
    'SKILL: Product-Themed Script Generator (curiosity through empathy, unbranded, enterprise AI).',
    'THE 1:1:1:1 RULE (non-negotiable): exactly ONE target audience, ONE trade (ONLY Timber Flooring, Windows, Blinds, Painting, Steel Fabrication or Contract Building), ONE pain point (from the database below, with its number) and ONE demo (ONLY: From Drawings to Estimate, Alfred AI Bid Management, AI Vendor Compliance Agent, AI Timber Quote Flooring Builder) that directly solves that pain point for that trade. Never blend. If the topic is broad, choose the single most natural matrix and say so in review_brief.checks.',
    'DEMO TO TRADE MAPPING:',
    '- From Drawings to Estimate: Contract Building, Windows, Blinds, Painting, Steel Fabrication. Audiences: Estimators, Builders, Trade Business Owners. Pains: manual takeoffs, missing details or variations in plans, inaccurate material quantities, 2D plans disconnected from pricing. Angle: complex drawing to accurate estimate without manual data entry.',
    '- Alfred AI Bid Management: Contract Building, Steel Fabrication. Audiences: Project Managers, Estimators, Builders. Pains: drowning in subcontractor quotes, missed bid deadlines, disorganised bid levelling, losing track of competitive pricing. Angle: collect, compare and manage bids in one place.',
    '- AI Vendor Compliance Agent: Contract Building, Steel Fabrication, Painting. Audiences: Project Managers, Business Owners, Admin Teams. Pains: expired insurance certificates, non-compliant subcontractors on site, tedious vendor onboarding, fragmented compliance documents. Angle: track, verify and collect vendor compliance documents.',
    '- AI Timber Quote Flooring Builder: Timber Flooring ONLY. Audiences: Flooring Contractors, Estimators. Pains: waste and board-length calculations, material types and finishes, slow quote turnaround, inconsistent pricing across reps. Angle: complex flooring quotes with every variable included.',
    '- Rotate: avoid the trade/demo combination of the recent scripts listed above.',
    'PAIN POINTS DATABASE (pick one; use its number):',
    painDb,
    'NARRATIVE MAPPING: Hook (audience + trade + specific tension, trade named in the first sentence) = Initial Anticipation. Problem agitation in the trade\'s exact vocabulary = Loading. Cost, risk, delay or missed opportunity = Rising Stakes. First layer of the solution, then "what a generic tool still cannot see" = Rehook. The one demo in operation - what it reads, prepares, routes, checks or records, and where the human stays responsible - plus orchestration, data governance, controlled access, auditability = Practical Payoff. One keyword (e.g. ESTIMATE, DRAWINGS, TENDER, COMPLIANCE, QUOTE) to comment or DM = CTA.',
    'GUARDRAILS (non-negotiable):',
    '- Never mention AlfredAI anywhere: script, captions, YouTube fields, ManyChat customer-facing copy, CTA. Say enterprise AI, governed workflow, workflow orchestration.',
    '- AI complements trade expertise; it never replaces it. Human-in-the-loop is explicit.',
    '- Contrast generic consumer AI with a governed workflow without insulting the audience.',
    '- No quantified impact (no "10x", "99%", "70%", ROI) - none has been supplied as approved evidence. State benefits qualitatively.',
    '- Say coordinate, check, route, prepare, record before "orchestration". No hype (revolutionary, perfect, guaranteed). The demo is practical, not magical.',
    '- ManyChat always applies: the keyword in the spoken CTA must match the ManyChat trigger.',
    'Every scene also needs voice_direction and motion (delivery note for the avatar) and a visual/demo note that matches what the demo can actually show.',
    'TARGET RUNTIME: ' + RUNTIME.Product + '.'
  ].join('\n');
  metaSpec = '{"target_audience": "", "trade": "", "pain_point": "number and name from the database", "demo": "", "cta_keyword": "", "target_runtime": "under 2 minutes"}';
}

const OUTPUT = [
  'OUTPUT: return ONE valid JSON object and nothing else (no markdown, no code fences). Keys:',
  '{',
  '  "metadata": ' + metaSpec + ',',
  '  "hook_family": "Controversy | Authority | Curiosity | Relatability | Storytelling",',
  '  "hook_format": "the exact hook format used",',
  '  "scenes": [ { "start": "m:ss", "end": "m:ss", "beat": "Initial Anticipation | Loading | Rising Stakes | Rehook | Practical Payoff | CTA", "spoken": "exact spoken copy", "purpose": "", "on_screen_text": "short overlay", "visual": "visual / editing note", "voice_direction": "", "motion": "" } ],',
  '  "editing_notes": ["editing rhythm, visual pacing, retention and rehook guidance"],',
  '  "captions": { "instagram": "", "tiktok": "", "linkedin": "", "youtube": "short-form or community post caption" },',
  '  "youtube": { "title": "", "alt_titles": ["", ""], "description": "paste-ready; the first two lines stand alone before Show more", "chapters": [ { "time": "0:00", "title": "" } ], "keywords": [""], "tags": [""], "hashtags": ["5-6, with #"], "thumbnail_text": "", "thumbnail_concept": "", "sources": ["source links or references for time-sensitive claims"], "publication_note": "what must be rechecked before publishing" },',
  '  "manychat": { "applicable": true, "keyword": "", "scope": "which Reel", "public_reply": "", "opening_dm": "explains the value of continuing", "button_label": "", "follow_up_dm": "with [APPROVED LINK] placeholder when relevant", "internal_tags": [""], "activation_checks": [""] },',
  '  "review_brief": { "hook_rationale": "why this family fits the topic and audience, and the previous-hook check", "beats": "how each of the six beats is used", "checks": ["facts, positions, sources or matrix choices a human must verify"], "guardrail_checks": "unbranded / no-product-pitch (News, Education) or 1:1:1:1, demo-to-pain, human-in-the-loop, data governance and claims (Product)", "cta": "the exact CTA and keyword", "runtime_pacing": "target runtime and pacing notes" },',
  '  "qa_checklist": [ { "item": "each item of this skill\'s quality checklist", "pass": true, "note": "" } ],',
  '  "estimated_runtime_seconds": 0',
  '}',
  'Rules for the JSON: chapters use the actual scene timings. If the CTA is only save, share or follow, set manychat.applicable to false and leave its other fields empty. Captions are unbranded, plain text, aligned with the script, add no new claims; Instagram 60-120 words with hashtags at the end, TikTok short hook plus 3-5 hashtags, LinkedIn 100-150 words professional.'
].join('\n');

const reference = transcript ? [
  'STRUCTURAL REFERENCE ONLY (another creator\'s published video, pattern: ' + (pattern['Reusable_Pattern'] || 'n/a') + '):',
  transcript,
  'SOURCE USE - NON-NEGOTIABLE: take only pacing and rhetorical shape from this reference. Do not reuse its sentences, phrasing, examples, analogies, statistics, claims or CTA keyword, and do not paraphrase it line by line. Your opening sentence must not resemble its opening sentence. If it is about another subject, ignore its content entirely.'
].join('\n') : '';

const sourceBlock = sourceText ? [
  'SOURCE MATERIAL (transcript of the video this idea came from' + (sourceName ? ', by ' + sourceName : '') + '):',
  sourceText,
  'Use it as the factual basis: attribute its claims to the creator (said, argued, warned...), separate fact from opinion, and do not copy its sentences, hook or CTA keyword.'
].join('\n') : 'SOURCE MATERIAL: none available. Work only from the topic; list every factual claim in review_brief.checks.';

const input = [
  'TOPIC: ' + topic,
  'CATEGORY ON RECORD: ' + (rawCategory || 'none') + ' (skill applied: ' + skill + ')',
  'PLATFORM: ' + platform + ' | CONTENT TYPE: ' + contentType,
  sourceName ? 'SOURCE NAME: ' + sourceName : '',
  sourceUrl ? 'SOURCE URL: ' + sourceUrl : '',
  angle ? 'APPROVED ANGLE FROM MARKETING REVIEW:\n' + angle : ''
].filter(Boolean).join('\n');

const prompt = [skillBlock, '', 'HOOK FAMILIES FOR THIS SKILL:', HOOKS[skill].map(h => '- ' + h).join('\n'), '', SHARED_RULES, '', reference, '', input, '', sourceBlock, '', OUTPUT].join('\n');

return { json: {
  record_id: record.id || '',
  topic: topic,
  platform: platform,
  content_type: contentType,
  category: rawCategory,
  skill: skill,
  previous_family: lastFamily,
  has_source: !!sourceText,
  pattern_name: pattern['Reusable_Pattern'] || 'Unknown Pattern',
  prompt: prompt
} };

// WF04 v3: turns the model's JSON into Airtable fields. Script = spoken copy only (WF06 sends it to HeyGen).
const response = $input.first().json;
const promptData = $('3. Build Viral-Aware Prompt').first().json;
const record = $('1c. Batch of 1').first().json;
const NL = '\n';
const sel = v => (v && typeof v === 'object') ? (v.name || '') : String(v || '');
const str = v => (v == null ? '' : String(v)).trim();
const arr = v => Array.isArray(v) ? v.map(str).filter(Boolean) : (str(v) ? [str(v)] : []);

let raw = '';
let out = null;
let parseError = '';
try {
  raw = response.choices[0].message.content || '';
  const finish = response.choices[0].finish_reason || '';
  out = JSON.parse(raw.replace(/```json/g, '').replace(/```/g, '').trim());
  if (finish === 'length') parseError = 'model output was cut off (max_tokens)';
} catch (e) {
  parseError = response.error ? ('OpenAI error: ' + (response.error.message || JSON.stringify(response.error))) : ('model did not return valid JSON: ' + e.message);
  out = null;
}

const scenes = (out && Array.isArray(out.scenes)) ? out.scenes.filter(s => s && str(s.spoken)) : [];
if (!parseError && !scenes.length) parseError = 'no scenes with spoken copy in the model output';
const ok = !parseError;

const cleanSpoken = t => str(t)
  .replace(/\[[^\]]*\]/g, '')
  .replace(/\*\*(.*?)\*\*/g, '$1').replace(/\*(.*?)\*/g, '$1')
  .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, '')
  .replace(/[ \t]+/g, ' ').trim();

let script = scenes.map(s => cleanSpoken(s.spoken)).filter(Boolean).join(NL + NL);
if (script.length > 5000) script = script.substring(0, 5000).trimEnd();

// Scene timings are recomputed from the spoken words at 130 wpm, so the brief and chapters match the real read.
const fmt = sec => Math.floor(sec / 60) + ':' + String(Math.round(sec % 60)).padStart(2, '0');
let cursor = 0;
const timed = scenes.map(s => {
  const w = cleanSpoken(s.spoken).split(/\s+/).filter(Boolean).length;
  const start = cursor; cursor += w / 130 * 60;
  return { ...s, start: fmt(Math.round(start)), end: fmt(Math.round(cursor)), start_sec: Math.round(start) };
});

// Runtime check at 130 wpm against the skill's target.
const words = script.split(/\s+/).filter(Boolean).length;
const estSeconds = Math.round(words / 130 * 60);
const TARGET = { News: [60, 90], Education: [45, 60], Product: [30, 119] };
const skill = promptData.skill || 'News';
