if (brandRe.test(instagramCaption)) brandHits.push('Instagram caption');
if (brandRe.test(tiktokCaption)) brandHits.push('TikTok caption');
if (brandRe.test(linkedinCaption)) brandHits.push('LinkedIn caption');
