    triggered = new Date(st).toISOString().substring(0, 16).replace('T', ' ');
    const secs = Math.max(0, Math.round((Date.now() - st) / 1000));
    runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's';
  }
} catch (e) {}

const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const NLs = '\n';
const block = sep + NLs + STAGE_TAG
