const prevBlock = ((freshNotes.match(blockRe) || [''])[0] || '').trim();
const notesBase = freshNotes.replace(blockRe, '').trim();

const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
let block = sep + '\n' + STAGE_TAG + '\nUpdated: ' + stamp + '\n' + g.gate_note;
if (g.mode !== 'unapproved' && prevBlock) {
