  if (prevBody) block += '\n\n' + prevBody;
}
const notesFinal = (notesBase ? notesBase + '\n\n' : '') + block;

return [{ json: { record_id: g.id, gate_status: g.gate_status, mode: g.mode, reel_notes_final: notesFinal } }];

